        const message = fields[name].validate(input.value);
        const show = forceShow || touched[name];

        setError(name, message, show);
        return !message;
      }

      function validateAll(forceShow = false) {
        return Object.keys(fields).every((name) => validateField(name, forceShow));
      }

      Object.entries(fields).forEach(([name, { input }]) => {
        input.addEventListener("blur", () => {
          touched[name] = true;
          validateField(name, true);
        });

        input.addEventListener("input", () => {
          validateField(name);
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        const isValid = validateAll(true);

        if (!isValid) {
          const firstInvalid = Object.values(fields).find(({ input }) => input.getAttribute("aria-invalid") === "true");
          firstInvalid?.input.focus();
          return;
        }

        status.textContent = "Thanks - your message is ready to send.";
      });
